add_action( 'rest_api_init', function () { register_rest_route( 'nadlan-dbg/v1', '/ps2', array( 'methods' => 'GET', 'permission_callback' => function(){ return current_user_can('manage_options'); }, 'callback' => function () { $out = array(); foreach ( get_posts( array( 'post_type' => 'nadlan_project', 'post_status' => 'publish', 'posts_per_page' => 40 ) ) as $p ) { $st = get_post_meta( $p->ID, 'project_status', true ); if ( strpos( $p->post_name, '-en' ) === false && strpos( $p->post_name, '-fr' ) === false && strpos( $p->post_name, '-ru' ) === false && strpos( $p->post_name, '-ar' ) === false ) { $out[] = array( 'id' => $p->ID, 'slug' => $p->post_name, 'status' => $st ); } } return $out; } ) ); } );